-- Synthetic objects for adapter tests. Not part of upstream; no real data.
CREATE TYPE public.todo_status AS ENUM ('open', 'done');

CREATE TABLE public.todos (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title text NOT NULL,
  status public.todo_status NOT NULL DEFAULT 'open',
  slug text UNIQUE,
  note text,
  created_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.todos IS 'Synthetic fixture table';
COMMENT ON COLUMN public.todos.title IS 'What to do';
ALTER TABLE public.todos ENABLE ROW LEVEL SECURITY;

CREATE TABLE public.tags (
  todo_id bigint NOT NULL REFERENCES public.todos (id) ON DELETE CASCADE,
  label text NOT NULL,
  PRIMARY KEY (todo_id, label)
);

INSERT INTO public.todos (title, slug) VALUES ('first', 'first'), ('second', 'second');

-- No primary key, a name that needs quoting, more rows than one page, and
-- values longer than the dashboard keeps.
CREATE TABLE public."Event ""Log""" (
  "Kind" text NOT NULL,
  payload jsonb,
  body text
);
INSERT INTO public."Event ""Log""" ("Kind", payload, body)
SELECT 'tick', jsonb_build_object('n', n), CASE WHEN n = 1 THEN repeat('z', 300) END
FROM generate_series(1, 120) AS n;

-- Foreign keys: one of two columns, declared in a different order from the
-- key, and one from a table to itself.
CREATE TABLE public.tag_notes (
  id bigint PRIMARY KEY,
  tag_label text NOT NULL,
  tag_todo bigint NOT NULL,
  parent_id bigint REFERENCES public.tag_notes (id) ON DELETE SET NULL,
  FOREIGN KEY (tag_todo, tag_label) REFERENCES public.tags (todo_id, label) ON UPDATE CASCADE
);
